'use client';

/*
 * VoiceGlow — 基于 MIT 开源库 voice-glow（libraries.dev）的演示封装
 * 声控辉光：从聊天输入框底部随语音升起的彩色光带
 * npm 依赖：voice-glow（MIT License, © Jakub Antalik）
 */
import { useRef, useState } from 'react';
import { VoiceBeam, useMicrophone } from 'voice-glow';
import NamedIcon from '../../components/NamedIcon';

export interface VoiceGlowProps {
  type?: 'default' | 'pill' | 'mobile';
  /** 色板：colorful / mono / ocean / sunset / forest / candy / ice / gold */
  colorVariant?: string;
  /** 思考模式：光带横扫（AI 回复生成中） */
  processing?: boolean;
  /** null/undefined = 跟随场景预设（pill 0.45 / 其他 1） */
  scale?: number | null;
  /** 静默时的呼吸底光 0-1 */
  idle?: number;
  sensitivity?: number;
  attack?: number;
  release?: number;
  /** simulate = 模拟语音；mic = 真实麦克风 */
  drive?: 'simulate' | 'mic';
}

// 模拟说话包络：语句节奏 × 音节起伏 × 停顿间隔，无需麦克风也有生动演示
function useSpeechSim() {
  const t0 = useRef(performance.now());
  const sample = () => {
    const t = (performance.now() - t0.current) / 1000;
    const phrase = Math.max(0, Math.sin(t * 0.5 - 0.4)); // 语句级呼吸（约 2/3 在说）
    const syllable = 0.45 + 0.55 * Math.abs(Math.sin(t * 6.1) * Math.sin(t * 2.3 + 1.7));
    const accent = 0.75 + 0.25 * Math.sin(t * 13.7);
    return Math.min(1, phrase * syllable * accent + 0.04);
  };
  return sample;
}

const VoiceGlow = ({
  type = 'default',
  colorVariant = 'colorful',
  processing = false,
  scale = null,
  idle = 0.35,
  sensitivity = 1.4,
  attack = 0.1,
  release = 0.5,
  drive = 'simulate'
}: VoiceGlowProps) => {
  const mic = useMicrophone();
  const simLevel = useSpeechSim();

  // 演示内容（按规范档位）
  const mock =
    type === 'pill' ? (
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--space-s)',
          padding: 'var(--space-s) var(--space-l)',
          background: 'var(--color-bg-elevated)',
          border: '1px solid var(--color-border-default)',
          borderRadius: 'var(--radius-full)',
          color: 'var(--color-text-muted)',
          fontSize: 'var(--text-sm)',
          fontWeight: 500
        }}
      >
        <NamedIcon name="mic-line" size={16} />
        Hold to talk
      </div>
    ) : type === 'mobile' ? (
      <div
        style={{
          width: 340,
          height: 420,
          borderRadius: 'var(--radius-xxl)',
          border: '1px solid var(--color-border-default)',
          background: 'linear-gradient(180deg, var(--color-bg-elevated) 0%, var(--color-bg-surface) 100%)',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'flex-end',
          padding: 'var(--space-l)',
          gap: 'var(--space-m)'
        }}
      >
        <div style={{ width: 140, height: 10, borderRadius: 'var(--radius-full)', background: 'var(--color-bg-active)' }} />
        <div style={{ width: 90, height: 10, borderRadius: 'var(--radius-full)', background: 'var(--color-bg-active)' }} />
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 'var(--space-s)',
            padding: 'var(--space-m)',
            borderRadius: 'var(--radius-m)',
            border: '1px solid var(--color-border-default)',
            color: 'var(--color-text-muted)',
            fontSize: 'var(--text-xs)'
          }}
        >
          <NamedIcon name="mic-line" size={14} /> Ask anything…
        </div>
      </div>
    ) : (
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--space-m)',
          width: 'min(420px, 70vw)',
          padding: 'var(--space-m) var(--space-m) var(--space-m) var(--space-l)',
          background: 'var(--color-bg-elevated)',
          border: '1px solid var(--color-border-default)',
          borderRadius: 'var(--radius-xxl)'
        }}
      >
        <NamedIcon name="mic-line" em={1.25} style={{ color: 'var(--color-text-muted)', display: 'inline-flex' }} />
        <span style={{ flex: 1, color: 'var(--color-text-muted)', fontSize: 'var(--text-sm)' }}>Ask anything…</span>
        <button
          type="button"
          aria-label="Send"
          className="pc-btn-hover pc-btn-brand"
          style={{
            width: 36,
            height: 36,
            padding: 0,
            borderRadius: 'var(--radius-full)',
            background: 'var(--color-primary)',
            color: 'var(--color-text-inverse)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            border: 'none',
            cursor: 'pointer',
            flexShrink: 0
          }}
        >
          <NamedIcon name="arrow-up-line" size={18} />
        </button>
      </div>
    );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 'var(--space-l)' }}>
      <VoiceBeam
        type={type}
        colorVariant={colorVariant as any}
        processing={processing}
        scale={scale ?? undefined}
        idle={idle}
        sensitivity={sensitivity}
        attack={attack}
        release={release}
        stream={drive === 'mic' ? mic.stream : null}
        level={drive === 'simulate' ? simLevel : undefined}
      >
        {mock}
      </VoiceBeam>

      {drive === 'mic' && (
        <button
          onClick={mic.state === 'live' ? mic.stop : mic.start}
          className={mic.state === 'live' ? 'pc-btn-hover pc-btn-brand' : 'pc-btn-hover pc-btn-soft'}
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 'var(--space-s)',
            padding: 'var(--space-xs) var(--space-m)',
            height: 32,
            borderRadius: 'var(--radius-m)',
            background: mic.state === 'live' ? 'var(--color-primary)' : 'var(--color-bg-elevated)',
            color: mic.state === 'live' ? 'var(--color-text-inverse)' : 'var(--color-text-secondary)',
            border: '1px solid ' + (mic.state === 'live' ? 'var(--color-primary)' : 'var(--color-border-default)'),
            cursor: 'pointer',
            fontSize: 'var(--text-sm)',
            fontWeight: 500
          }}
        >
          <NamedIcon name={mic.state === 'live' ? 'mic-off-line' : 'mic-line'} size={14} />
          {mic.state === 'live' ? 'Listening… tap to stop' : mic.state === 'requesting' ? 'Requesting…' : 'Tap to listen'}
        </button>
      )}
    </div>
  );
};

export default VoiceGlow;
